/* harmony default export */ __webpack_exports__["default"] = ({
  onLoad(e) {
    this.order_sn = e.order_sn || '';
  },
  onShow() {
    this.getOrderDetail();
  },
  computed: {
    // 价格小数
    priceDecimal() {
      return val => {
        if (val !== parseInt(val)) return val.slice(-2);else return '00';
      };
    },
    // 价格整数
    priceInt() {
      return val => {
        if (val !== parseInt(val)) return val.split('.')[0];else return val;
      };
    }
  },
  data() {
    return {
      id: '',
      info: {},
      show: false,
      loading: true,
      is_refund: false,
      order_goods_id: ''
    };
  },
  methods: {
    getOrderDetail() {
      this.$api.orderDetail({
        order_sn: this.order_sn
      }).then(res => {
        if (res.code == 1) {
          this.info = res.data;
          this.loading = false;
        } else {
          this.$u.toast(res.msg);
          setTimeout(() => {
            uni.$u.route({
              type: 'back'
            });
          }, 1500);
        }
        uni.stopPullDownRefresh();
      });
    },
    shipped() {
      this.$api.takedelivery({
        order_sn: this.order_sn
      }).then(res => {
        this.$u.toast(res.msg);
        if (res.code) {
          this.getOrderDetail();
        }
      });
    },
    refund() {
      this.$api.ordeAfterSaleApply({
        id: this.order_goods_id,
        type: 1
      }).then(res => {
        this.$u.toast(res.msg);
        if (res.code) {
          this.getOrderDetail();
        }
      });
    },
    cancel() {
      this.$api.orderCancel({
        order_sn: this.order_sn
      }).then(res => {
        this.$u.toast(res.msg);
        if (res.code == 1) {
          this.getOrderDetail();
        }
      });
    },
    //复制订单编号
    copy() {
      this.$util.uniCopy({
        content: this.info.order_sn,
        success: () => {
          this.$u.toast('订单编号已复制');
        }
      });
    }
  },
  onPullDownRefresh() {
    this.getOrderDetail();
  }
});

